// load
window.onload = function () {
    'use strict';

    document.getElementById("cpx").addEventListener("input", e => {
        const t = e.target.value;
        document.getElementById("currentColor").value = t.replace("#", "")
    });

    cmr_codesnip = CodeMirror.fromTextArea(document.getElementById("codesnip"), {
        lineNumbers: true,
        theme: "monokai",
        mode: "htmlmixed"
    });
    
    cmr_cssgradient = CodeMirror.fromTextArea(document.getElementById("cssgradient"), {
        lineNumbers: true,
        lineWrapping: true,
        theme: "monokai",
        mode: "javascript"
    });

    cmr_codecssbeautify = CodeMirror.fromTextArea(document.getElementById("codecssbeautify"), {
        lineNumbers: true,
        lineWrapping: true,
        theme: "monokai",
        mode: "css",
        onChange: rapihkancss
    });

    cmr_rescssbeautify = CodeMirror.fromTextArea(document.getElementById("rescssbeautify"), {
        lineNumbers: true,
        theme: "monokai",
        mode: "css",
        readOnly: true
    });

    cmr_codecssminify = CodeMirror.fromTextArea(document.getElementById("codecssminify"), {
        lineNumbers: true,
        theme: "monokai",
        mode: "css",
        onChange: cssminify
    });

    cmr_rescssminify = CodeMirror.fromTextArea(document.getElementById("rescssminify"), {
        lineNumbers: true,
        lineWrapping: true,
        theme: "monokai",
        mode: "css",
        readOnly: true
    });

    cmr_cssgradient.setSize(null, 44);
};

